package ama.storage;
import java.nio.file.*;import java.util.*;import com.fasterxml.jackson.databind.JsonNode;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
/** Actual continuation finally/finish control flow with only full-row read replaced offline. */
class Task11B3ContinuationFinalizationTest {
 @TempDir Path evidence;
 class Fixture extends Task11B3ContinuationIT {Map<String,List<Map<String,Object>>> observed;@Override Map<String,List<Map<String,Object>>> finalRows(){return observed;}}
 Fixture setup(Fixture t)throws Exception {var data=new Task11B3ContinuationOracleTest();data.data();t.f.initial=data.before;t.f.keys.putAll(data.keys);t.f.tasks.addAll(List.of("t1","t2"));t.f.executions.addAll(List.of("e1","e2"));t.f.sealed.addAll(data.sealed);t.f.meeting="m";t.f.publication="p";t.f.operation="o";t.finalExpected=Task11B3LifecycleOracleTest.copy(data.after);t.observed=Task11B3LifecycleOracleTest.copy(data.after);t.databaseVerified=true;t.f.complete=true;Path root=Path.of(System.getenv("AMA_TASK11_REPOSITORY_ROOT"));var empty=Task11B2RuntimeFixture.JSON.createObjectNode();t.f.inputs=new Task11B3LifecycleInputs.Inputs(root,root.resolve(".superpowers/sdd/2026-10-23-ama-phase-b-remaining"),root.resolve(".tools/unused-offline"),evidence,empty,empty,empty,empty);return t;}
 JsonNode result()throws Exception {return Task11B2RuntimeFixture.JSON.readTree(Files.readAllBytes(evidence.resolve("b3-lifecycle-result.json")));}
 void unqualified()throws Exception {var r=result();assertEquals("PARTIAL_UNQUALIFIED",r.path("status").asText());assertFalse(r.path("events").get(r.path("events").size()-1).at("/facts/qualified").asBoolean(true));}
 @Test void terminalRootDriftCannotPassAfterCompletedSequence()throws Exception {var t=setup(new Fixture());t.observed.get("publication").getFirst().put("revision",20);assertThrows(AssertionError.class,()->t.finish(null));unqualified();assertEquals(20,Task11B2RuntimeFixture.JSON.readTree(Files.readAllBytes(evidence.resolve("business-final-custody.json"))).path("publication").get(0).path("revision").asInt());}
 @Test void finalDriftIsSuppressedUnderPrimaryAndSaved()throws Exception {var t=setup(new Fixture());t.observed.get("publication").getFirst().put("revision",20);var primary=new IllegalStateException("primary");t.finish(primary);assertEquals(1,primary.getSuppressed().length);unqualified();}
 @Test void exactFinalRowsPass()throws Exception {var t=setup(new Fixture());t.finish(null);assertEquals("PASS",result().path("status").asText());assertTrue(Files.isRegularFile(evidence.resolve("business-final-custody.json")));}
 @Test void readFailureCannotPass()throws Exception {var t=setup(new Fixture(){@Override Map<String,List<Map<String,Object>>> finalRows(){throw new IllegalStateException("read");}});assertThrows(IllegalStateException.class,()->t.finish(null));unqualified();}
 @Test void saveFailureCannotPass()throws Exception {var t=setup(new Fixture(){@Override void saveFinal(Object rows)throws Exception {throw new java.io.IOException("save");}});assertThrows(java.io.IOException.class,()->t.finish(null));unqualified();}
 @Test void closeFailureStillSavesAndSuppressesUnderPrimary()throws Exception {var t=setup(new Fixture(){@Override void closeOwned(){throw new IllegalStateException("close");}});var primary=new IllegalStateException("primary");t.finish(primary);assertEquals(1,primary.getSuppressed().length);assertTrue(Files.isRegularFile(evidence.resolve("business-final-custody.json")));unqualified();}
}